The computations are as follows:


::: {.cell}

```{.r .cell-code  code-fold="true"}
y <- outlier_data$Value
n <- length(y)

med <- median(y)
q1 <- quantile(y, 0.25, type = 6, names = FALSE)
q3 <- quantile(y, 0.75, type = 6, names = FALSE)
iq <- q3 - q1

tibble(
  Statistic = c("Median", "Lower quartile", "Upper quartile", "Interquartile range", "Lower inner fence", "Upper inner fence", "Lower outer fence", "Upper outer fence"),
  Value = c(med, q1, q3, iq, q1 - 1.5 * iq, q3 + 1.5 * iq, q1 - 3 * iq, q3 + 3 * iq)
) |>
  knitr::kable(digits = 2, align = "lr")
```

